<div class="modulo-cabecalho"><div><h1><i class="fa-solid fa-building-gear"></i> Configurações da empresa</h1><p>Personalize as preferências visuais e de notificações da sua empresa.</p></div></div><form method="post" action="<?php echo URL_BASE; ?>/configuracoes/guardar" class="config-form"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf_token); ?>"><input type="hidden" name="contexto" value="empresa"><section class="config-cartao"><h2><i class="fa-solid fa-palette"></i> Aparência</h2><div class="config-grid"><?php foreach(['cor_primaria'=>'Cor principal','cor_secundaria'=>'Cor secundária'] as $k=>$l): ?><label><?php echo $l; ?><input name="configuracoes[<?php echo $k; ?>]" placeholder="#0e2748" value="<?php echo htmlspecialchars($configuracoes[$k]??''); ?>"></label><?php endforeach; ?></div></section><section class="config-cartao"><h2><i class="fa-solid fa-bell"></i> Notificações</h2><div class="config-grid"><?php foreach(['notificacoes_email'=>'Notificações por e-mail','notificacoes_sistema'=>'Notificações no sistema'] as $k=>$l): ?><label><?php echo $l; ?><select name="configuracoes[<?php echo $k; ?>]"><option value="1" <?php echo ($configuracoes[$k]??'1')==='1'?'selected':''; ?>>Ativadas</option><option value="0" <?php echo ($configuracoes[$k]??'')==='0'?'selected':''; ?>>Desativadas</option></select></label><?php endforeach; ?></div></section><button class="btn btn-primary"><i class="fa-solid fa-floppy-disk"></i> Guardar configurações</button></form><?php require CAMINHO_RAIZ.'/views/configuracoes/_estilos.php'; ?>
